package com.example.medilinkchain;

import java.io.Serializable;
import java.util.Date;

/**
 * DoctorInvitationModel — Model representing doctor registration invitations generated by Hospital Admins.
 */
public class DoctorInvitationModel implements Serializable {
    private String id;
    private String organizationId;
    private String registrationId; // e.g. DOC-ABC-2026-0001
    private String hospitalName;
    private String hospitalCode;
    private String doctorName;
    private String specialization;
    private String email;
    private String phone;
    private String medicalRegistrationNumber;
    private String status; // ACTIVE, USED, EXPIRED, CANCELLED
    private String createdBy;
    private Date expiresAt;
    private Date createdAt;
    private Date updatedAt;

    public DoctorInvitationModel() {
        this.status = "ACTIVE";
        this.createdAt = new Date();
    }

    public DoctorInvitationModel(
            String id,
            String organizationId,
            String registrationId,
            String doctorName,
            String specialization,
            String email,
            String phone,
            String medicalRegistrationNumber,
            String status,
            String createdBy,
            Date expiresAt,
            Date createdAt) {
        this.id = id;
        this.organizationId = organizationId;
        this.registrationId = registrationId;
        this.doctorName = doctorName;
        this.specialization = specialization;
        this.email = email;
        this.phone = phone;
        this.medicalRegistrationNumber = medicalRegistrationNumber;
        this.status = status != null ? status.toUpperCase() : "ACTIVE";
        this.createdBy = createdBy;
        this.expiresAt = expiresAt;
        this.createdAt = createdAt != null ? createdAt : new Date();
    }

    public String getId() {
        return id != null ? id : "";
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getOrganizationId() {
        return organizationId != null ? organizationId : "";
    }

    public void setOrganizationId(String organizationId) {
        this.organizationId = organizationId;
    }

    public String getRegistrationId() {
        return registrationId != null ? registrationId : "";
    }

    public void setRegistrationId(String registrationId) {
        this.registrationId = registrationId;
    }

    public String getHospitalName() {
        return hospitalName != null ? hospitalName : "";
    }

    public void setHospitalName(String hospitalName) {
        this.hospitalName = hospitalName;
    }

    public String getHospitalCode() {
        return hospitalCode != null ? hospitalCode : "";
    }

    public void setHospitalCode(String hospitalCode) {
        this.hospitalCode = hospitalCode;
    }

    public String getDoctorName() {
        return doctorName != null ? doctorName : "";
    }

    public void setDoctorName(String doctorName) {
        this.doctorName = doctorName;
    }

    public String getSpecialization() {
        return specialization != null ? specialization : "General Medicine";
    }

    public void setSpecialization(String specialization) {
        this.specialization = specialization;
    }

    public String getEmail() {
        return email != null ? email : "";
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPhone() {
        return phone != null ? phone : "";
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }

    public String getMedicalRegistrationNumber() {
        return medicalRegistrationNumber != null ? medicalRegistrationNumber : "";
    }

    public void setMedicalRegistrationNumber(String medicalRegistrationNumber) {
        this.medicalRegistrationNumber = medicalRegistrationNumber;
    }

    public String getStatus() {
        return status != null ? status.toUpperCase() : "ACTIVE";
    }

    public void setStatus(String status) {
        this.status = status != null ? status.toUpperCase() : "ACTIVE";
    }

    public String getCreatedBy() {
        return createdBy != null ? createdBy : "";
    }

    public void setCreatedBy(String createdBy) {
        this.createdBy = createdBy;
    }

    public Date getExpiresAt() {
        return expiresAt;
    }

    public void setExpiresAt(Date expiresAt) {
        this.expiresAt = expiresAt;
    }

    public Date getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Date createdAt) {
        this.createdAt = createdAt;
    }

    public Date getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Date updatedAt) {
        this.updatedAt = updatedAt;
    }

    public boolean isActive() {
        return "ACTIVE".equalsIgnoreCase(status) && (expiresAt == null || expiresAt.after(new Date()));
    }
}
